Assume a 32-bit `int` and that `int16_t` holds Q15 values. What does this print?

```c
#include <stdint.h>
#include <stdio.h>
int main(void)
{
    int16_t a = 0x4000;   /* 0.5  in Q15 */
    int16_t b = 0x2000;   /* 0.25 in Q15 */
    int16_t p = (int16_t)(((int32_t)a * b) >> 15);
    printf("%d %d\n", p, (int)(((int32_t)a * b) >> 14));
    return 0;
}
```

Assume a 32-bit `int`. `a` holds $0.5$ in Q15, and `b` holds $0.25$ in Q14 (that is, $Q1.14$, scale $2^{-14}$). What does this print, and which value is the correct Q15 sum $0.75$?

```c
#include <stdint.h>
#include <stdio.h>
int main(void)
{
    int16_t a = 16384;
    int16_t b = 4096;
    int16_t bad  = a + b;
    int16_t good = a + (int16_t)(b << 1);
    printf("%d %d\n", bad, good);
    return 0;
}
```

Assume `float` is IEEE 754 float32 and `unsigned` is 32 bits. What does this print?

```c
#include <stdio.h>
#include <string.h>
int main(void)
{
    float f = 0.15625f;   /* 5/32 */
    unsigned u;
    memcpy(&u, &f, sizeof u);
    printf("%08x %u\n", u, (u >> 23) & 0xFFu);
    return 0;
}
```

Assume `float` is float32. This code converts a float to BF16 by keeping the top 16 bits, then widens it back. What does it print?

```c
#include <stdint.h>
#include <stdio.h>
#include <string.h>
int main(void)
{
    float f = 3.14159f;
    uint32_t u;  memcpy(&u, &f, sizeof u);
    uint16_t bf = (uint16_t)(u >> 16);
    uint32_t back = (uint32_t)bf << 16;
    float g;  memcpy(&g, &back, sizeof g);
    printf("%04x %.6f\n", (unsigned)bf, (double)g);
    return 0;
}
```

Assume 16-bit `int16_t` and 32-bit `int`. What does this program print?

```c
#include <stdint.h>
#include <stdio.h>
static int16_t sat_add16(int16_t a, int16_t b)
{
    int32_t s = (int32_t)a + b;
    if (s > INT16_MAX) return INT16_MAX;
    if (s < INT16_MIN) return INT16_MIN;
    return (int16_t)s;
}
int main(void)
{
    printf("%d %d %d\n", sat_add16(30000, 10000),
           sat_add16(-30000, -10000), sat_add16(100, -200));
    return 0;
}
```

On a GCC target (32-bit `int`; converting an out-of-range value to `int16_t` wraps), what does this print, and what is the fix for the first line?

```c
#include <stdint.h>
#include <stdio.h>
int main(void)
{
    int16_t a = -32768, b = -32768;   /* both -1.0 in Q15 */
    int16_t p = (int16_t)(((int32_t)a * b) >> 15);
    printf("%d\n", p);
    int32_t full = ((int32_t)a * b) >> 15;
    printf("%d\n", (int)full);
    return 0;
}
```

Assume a Cortex-M4 project whose CMSIS device header provides the intrinsics `__SSAT` and `__USAT`. What do the four calls return, and which Arm instruction does `clip16` compile to?

```c
#include <stdint.h>
/* device header included here */
int16_t clip16(int32_t x) { return (int16_t)__SSAT(x, 16); }
uint8_t clip8u(int32_t x) { return (uint8_t)__USAT(x, 8); }
/* clip16(40000)  clip16(-40000)  clip8u(300)  clip8u(-5) */
```

Assume 32-bit `int` and that converting an out-of-range value to `int16_t` wraps (as GCC does). What does this print, and why do int8 dot products use an `int32_t` accumulator?

```c
#include <stdint.h>
#include <stdio.h>
int main(void)
{
    int8_t x[4] = {-128, -128, -128, -128};
    int8_t w[4] = {-128, -128, -128, -128};
    int16_t s16 = 0;
    int32_t s32 = 0;
    for (int i = 0; i < 4; i++) {
        s16 = (int16_t)(s16 + x[i] * w[i]);
        s32 += x[i] * w[i];
    }
    printf("%d %d\n", s16, (int)s32);
    return 0;
}
```
